package com.example.data.local.entity

import androidx.room.Entity
import androidx.room.PrimaryKey

/**
 * Room entity representing a saved text-based creative concept or storyboard
 * generated by STAR ARTIST STUDIO Gemini AI.
 */
@Entity(tableName = "generation_history")
data class GenerationHistoryEntity(
    @PrimaryKey(autoGenerate = true)
    val id: Long = 0,
    val category: String, // "photo" or "video"
    val title: String,
    val parametersSummary: String,
    val content: String,
    val timestamp: Long = System.currentTimeMillis()
)
